-- Hand-written: grants, row-level security and checks.
-- No DELETE grant: incidents are never deleted (security.md §4.5).
GRANT SELECT, INSERT, UPDATE ON "tenant"."incidents" TO safezone_app;
GRANT SELECT, INSERT ON "tenant"."incident_evidence" TO safezone_app;
GRANT SELECT, INSERT ON "tenant"."incident_notes" TO safezone_app;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['incidents','incident_evidence','incident_notes'] LOOP
    EXECUTE format('ALTER TABLE "tenant".%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE "tenant".%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY %I ON "tenant".%I FOR ALL TO safezone_app
      USING (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)
      WITH CHECK (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)$p$, t || '_tenant', t);
  END LOOP;
END $$;
ALTER TABLE "tenant"."incidents" ADD CONSTRAINT incidents_category_check CHECK (category IN
  ('suspicious_activity','unauthorised_access','theft','fight','fire','accident','damage','other'));
ALTER TABLE "tenant"."incidents" ADD CONSTRAINT incidents_severity_check
  CHECK (severity IN ('low','medium','high','critical'));
ALTER TABLE "tenant"."incidents" ADD CONSTRAINT incidents_status_check
  CHECK (status IN ('reported','under_review','assigned','resolved','closed'));
ALTER TABLE "tenant"."incidents" ADD CONSTRAINT incidents_location_kind_check
  CHECK (location_kind IN ('gate','unit','common_area','other'));
ALTER TABLE "tenant"."incidents" ADD CONSTRAINT incidents_reporter_type_check
  CHECK (reporter_type IN ('guard','resident','manager'));
-- Evidence and the timeline are records of what happened: append-only.
CREATE TRIGGER incident_evidence_append_only BEFORE UPDATE OR DELETE ON "tenant"."incident_evidence"
  FOR EACH ROW EXECUTE FUNCTION audit.reject_mutation();
CREATE TRIGGER incident_notes_append_only BEFORE UPDATE OR DELETE ON "tenant"."incident_notes"
  FOR EACH ROW EXECUTE FUNCTION audit.reject_mutation();
